// Worker entry point: OpenNext's Next.js handler, plus the media processor container class,
// which Cloudflare needs exported from the Worker that binds it.
// Generated by `opennextjs-cloudflare build`, so it only exists after a build: @ts-expect-error
// would fail whenever it does exist.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,
} satisfies ExportedHandler<CloudflareEnv>;

export { MediaProcessor } from "./processor/container";
